import * as THREE from 'three';

import type {
  Filament,
} from './filaments';


const FOUR_PI = 4 * Math.PI;


/**
 * Magnetic field generated by a fixed
 * collection of current filaments.
 *
 * The field is NOT normalized.
 */
export class MagneticField {

  private filaments: Filament[];


  constructor(
    filaments: Filament[]
  ) {

    this.filaments =
      filaments;
  }


  /**
   * Magnetic field B(r).
   *
   * The returned vector keeps its magnitude.
   */
  B(
    position: THREE.Vector3
  ): THREE.Vector3 {

    const B =
      new THREE.Vector3();


    for (
      const filament
      of this.filaments
    ) {

      const points =
        filament.points;

      const current =
        filament.current;


      for (
        let i = 0;
        i < points.length;
        i++
      ) {

        const a =
          points[i];

        const b =
          points[
            (i + 1) % points.length
          ];


        const dl =
          new THREE.Vector3()
            .subVectors(
              b,
              a
            );


        const midpoint =
          new THREE.Vector3()
            .addVectors(
              a,
              b
            )
            .multiplyScalar(0.5);


        const r =
          new THREE.Vector3()
            .subVectors(
              position,
              midpoint
            );


        const r2 =
          r.lengthSq();


        if (r2 < 1e-10) {
          continue;
        }


        const rLength =
          Math.sqrt(r2);


        const contribution =
          new THREE.Vector3()
            .crossVectors(
              dl,
              r
            );


        contribution.multiplyScalar(
          current /
          (
            FOUR_PI *
            rLength *
            rLength *
            rLength
          )
        );


        B.add(
          contribution
        );
      }
    }


    return B;
  }


  /**
   * Unit vector along B.
   *
   * Used by field-line integration.
   */
  direction(
    position: THREE.Vector3
  ): THREE.Vector3 {

    const B =
      this.B(position);

    const magnitude =
      B.length();


    if (
      magnitude < 1e-12
    ) {

      return new THREE.Vector3();
    }


    return B.multiplyScalar(
      1 / magnitude
    );
  }
}
